<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { CalendarPlus2, Check, Copy, ExternalLink, Info, MessageSquareText, RefreshCw, Save, X } from 'lucide-vue-next'

type View=''|'booking'|'messages'
type Envelope<T>={data?:T;error?:{message?:string}}
type Capabilities={enabled:string[]}
type TenantSettings={hostname:string;preferences:Record<string,unknown>}
type NotificationTemplate={id:string;key:string;channel:string;body:string;active:boolean;subject?:string|null}
type BookingParameters={service_mode:string;email_mode:string;phone_mode:string;duration_mode:string;professional_mode:string;default_professional_name:string;simultaneous:{enforce_public:boolean;capacity:number}}

const active=ref<View>('')
const portalReady=ref(false)
const loading=ref(false)
const saving=ref(false)
const error=ref('')
const toast=ref('')
const capabilities=ref(new Set<string>())
const hostname=ref(window.location.hostname)
const templates=ref<NotificationTemplate[]>([])
const parameters=ref<BookingParameters|null>(null)
const booking=ref({enabled:false,title:'Agende seu atendimento',subtitle:'Escolha o melhor horário para você.',success_message:'Seu horário foi reservado.',custom_html:'',slot_minutes:30,allow_any_professional:true})

const token=()=>localStorage.getItem('scheduler_pro_access_token')||''
const canBooking=computed(()=>capabilities.value.has('public_booking'))
const canMessages=computed(()=>capabilities.value.has('notifications'))
const publicUrl=computed(()=>`${window.location.origin}/agendar`)
const whatsappTemplates=computed(()=>templates.value.filter(item=>item.channel==='whatsapp'))
const emailTemplates=computed(()=>templates.value.filter(item=>item.channel==='email'))
const variableHelp='{{customer_name}} · {{service_name}} · {{professional_name}} · {{starts_at_br}} · {{ends_at_br}} · {{confirmation_url}} · {{reason}}'

const labels:Record<string,string>={
  appointment_created:'Reserva criada',appointment_confirmation_request:'Pedido de confirmação',appointment_rescheduled:'Reagendamento',appointment_confirmed:'Confirmação concluída',appointment_cancelled:'Cancelamento',appointment_completed:'Atendimento concluído',appointment_no_show:'Não comparecimento',appointment_reminder_24h:'Lembrete 24 horas',appointment_reminder_2h:'Lembrete 2 horas',appointment_confirmation_request_email:'Pedido de confirmação',appointment_rescheduled_email:'Reagendamento',appointment_confirmed_email:'Confirmação concluída',appointment_cancelled_email:'Cancelamento',appointment_reminder_24h_email:'Lembrete 24 horas',appointment_reminder_2h_email:'Lembrete 2 horas',tenant_confirmation_confirmed:'Cliente confirmou o horário',tenant_confirmation_cancelled:'Cliente cancelou o horário',tenant_confirmation_expired:'Prazo de confirmação expirou',agenda_management_report:'Relatório gerencial da Agenda',
}
const helps:Record<string,string>={
  appointment_created:'Enviada quando um novo atendimento é criado.',appointment_confirmation_request:'Solicita ao cliente que confirme o horário reservado.',appointment_rescheduled:'Informa alteração de data ou horário.',appointment_confirmed:'Confirma que o horário está validado.',appointment_cancelled:'Informa o cancelamento e a liberação do horário.',appointment_completed:'Mensagem opcional após a conclusão.',appointment_no_show:'Mensagem referente ao não comparecimento.',appointment_reminder_24h:'Lembrete antecipado do atendimento.',appointment_reminder_2h:'Lembrete próximo ao horário.',tenant_confirmation_confirmed:'Retorno automático após a confirmação do cliente.',tenant_confirmation_cancelled:'Retorno automático após o cancelamento pelo cliente.',tenant_confirmation_expired:'Aviso quando o prazo de confirmação termina.',agenda_management_report:'Resumo gerencial programado pelo responsável da empresa.',
}
function friendlyKey(value:string){return labels[value]||'Mensagem automática da Agenda'}
function templateHelp(value:string){return helps[value]||helps[value.replace('_email','')]||'Mensagem automática vinculada a uma etapa do atendimento.'}
function showToast(value:string){toast.value=value;window.setTimeout(()=>{if(toast.value===value)toast.value=''},3500)}
async function api<T>(path:string,init:RequestInit={}):Promise<T>{const response=await fetch(`${window.location.origin}/api/v1${path}`,{...init,cache:'no-store',headers:{Accept:'application/json',...(init.body?{'content-type':'application/json'}:{}),...(token()?{Authorization:`Bearer ${token()}`}:{}) ,...(init.headers||{})}});const payload=await response.json().catch(()=>({})) as Envelope<T>;if(!response.ok||payload.data===undefined)throw new Error(payload.error?.message||`Não foi possível concluir a operação (${response.status}).`);return payload.data}
function boolValue(value:unknown,fallback:boolean){return typeof value==='boolean'?value:fallback}
function numberValue(value:unknown,fallback:number){const parsed=Number(value);return Number.isFinite(parsed)?parsed:fallback}
function stringValue(value:unknown,fallback:string){return typeof value==='string'?value:fallback}
async function initialLoad(){try{const caps=await api<Capabilities>('/settings/capabilities');capabilities.value=new Set(caps.enabled||[])}catch{/* console principal permanece */}}
async function loadBooking(){const [data,params]=await Promise.all([api<TenantSettings>('/settings/tenant'),api<BookingParameters>('/settings/booking')]);hostname.value=data.hostname||window.location.hostname;parameters.value=params;const p=data.preferences||{};booking.value={enabled:boolValue(p.public_booking_enabled,false),title:stringValue(p.public_booking_title,'Agende seu atendimento'),subtitle:stringValue(p.public_booking_subtitle,'Escolha o melhor horário para você.'),success_message:stringValue(p.public_booking_success_message,'Seu horário foi reservado.'),custom_html:stringValue(p.public_booking_custom_html,''),slot_minutes:numberValue(p.public_booking_slot_minutes,30),allow_any_professional:boolValue(p.public_booking_allow_any_professional,true)}}
async function loadMessages(){templates.value=await api<NotificationTemplate[]>('/notifications/templates')}
async function open(view:View){active.value=view;error.value='';loading.value=true;try{if(view==='booking')await loadBooking();if(view==='messages')await loadMessages()}catch(exc){error.value=exc instanceof Error?exc.message:'Não foi possível carregar esta área.'}finally{loading.value=false}}
function close(){active.value='';if(['#agenda-publica','#mensagens'].includes(window.location.hash))window.location.hash='dashboard'}
function routeView():View{const hash=(window.location.hash||'').replace(/^#/,'');return hash==='agenda-publica'?'booking':hash==='mensagens'?'messages':''}
async function syncRoute(){const next=routeView();if(next&&next!==active.value)await open(next);else if(!next&&active.value)active.value=''}
function onRouteChange(){void syncRoute()}
async function putSetting(key:string,value:unknown){await api(`/settings/tenant/${key}`,{method:'PUT',body:JSON.stringify(value)})}
async function saveBooking(){saving.value=true;error.value='';try{await Promise.all([putSetting('public_booking_enabled',booking.value.enabled),putSetting('public_booking_title',booking.value.title),putSetting('public_booking_subtitle',booking.value.subtitle),putSetting('public_booking_success_message',booking.value.success_message),putSetting('public_booking_custom_html',booking.value.custom_html),putSetting('public_booking_slot_minutes',Math.max(5,Math.min(240,Number(booking.value.slot_minutes)||30))),putSetting('public_booking_allow_any_professional',booking.value.allow_any_professional)]);showToast('Página de agendamento atualizada.')}catch(exc){error.value=exc instanceof Error?exc.message:'Falha ao salvar a página de agendamento.'}finally{saving.value=false}}
async function saveTemplate(item:NotificationTemplate){saving.value=true;error.value='';try{const saved=await api<NotificationTemplate>(`/notifications/templates/${encodeURIComponent(item.key)}`,{method:'PUT',body:JSON.stringify({channel:item.channel,body:item.body,active:item.active,subject:item.subject||null})});Object.assign(item,saved);showToast(`${friendlyKey(item.key)} salva.`)}catch(exc){error.value=exc instanceof Error?exc.message:'Falha ao salvar a mensagem.'}finally{saving.value=false}}
async function copyPublicUrl(){await navigator.clipboard.writeText(publicUrl.value);showToast('Link copiado.')}
function openPublic(){window.open(publicUrl.value,'_blank','noopener')}
function modeLabel(value?:string){return value==='DISABLED'?'Oculto':value==='OPTIONAL'?'Opcional':'Obrigatório'}

onMounted(async()=>{await nextTick();portalReady.value=Boolean(document.querySelector('.tenant-console .main-content'));await initialLoad();window.addEventListener('hashchange',onRouteChange);await syncRoute()})
onUnmounted(()=>{window.removeEventListener('hashchange',onRouteChange);document.body.classList.remove('sp-booking-message-open')})
</script>

<template>
  <Teleport v-if="portalReady&&active" to=".tenant-console .main-content">
    <section class="sp-extension-root sp-booking-message-root">
      <header class="sp-extension-header"><div><span>Scheduler Pro</span><h1>{{active==='booking'?'Página de agendamento':'Mensagens da Agenda'}}</h1><p>{{active==='booking'?'Configure a experiência pública sem duplicar as regras do modelo de negócio da Agenda.':'Personalize, em linguagem simples, o que seus clientes recebem por WhatsApp e e-mail.'}}</p></div><button class="sp-icon-button" @click="close"><X :size="20"/></button></header>
      <p v-if="toast" class="sp-success"><Check :size="16"/>{{toast}}</p><p v-if="error" class="sp-error">{{error}}</p><div v-if="loading" class="sp-config-loading"><RefreshCw :size="20" class="spin"/>Atualizando...</div>

      <template v-else-if="active==='booking'">
        <div class="sp-booking-config-grid">
          <article class="sp-config-card"><div class="sp-config-card-head"><div><span>Publicação</span><h2>Agenda online</h2></div><label class="sp-switch"><input v-model="booking.enabled" type="checkbox"/><i></i><b>{{booking.enabled?'Ativa':'Desativada'}}</b></label></div><p>Quando ativa, o cliente acessa uma página pública ligada ao mesmo motor da Agenda.</p><div class="sp-public-url"><code>{{publicUrl}}</code><button @click="copyPublicUrl"><Copy :size="16"/></button><button @click="openPublic"><ExternalLink :size="16"/></button></div><div class="sp-config-form"><label>Título<input v-model="booking.title"/></label><label>Subtítulo<textarea v-model="booking.subtitle" rows="3"/></label><label>Mensagem após reservar<textarea v-model="booking.success_message" rows="3"/></label></div></article>
          <article class="sp-config-card"><span class="sp-card-kicker">Comportamento</span><h2>Regras herdadas da Agenda</h2><p>A obrigatoriedade dos campos não é duplicada aqui. Ela vem do Modelo de negócio da Agenda e o campo desaparece automaticamente quando estiver desativado.</p><div class="sp-rule-summary"><div><span>Telefone</span><strong>{{modeLabel(parameters?.phone_mode)}}</strong></div><div><span>E-mail</span><strong>{{modeLabel(parameters?.email_mode)}}</strong></div><div><span>Serviço</span><strong>{{modeLabel(parameters?.service_mode)}}</strong></div><div><span>Profissional</span><strong>{{modeLabel(parameters?.professional_mode)}}</strong></div><div><span>Tempo</span><strong>{{modeLabel(parameters?.duration_mode)}}</strong></div><div><span>Capacidade</span><strong>{{parameters?.simultaneous.enforce_public?(parameters?.simultaneous.capacity||1)+' vaga(s)':'Agenda livre'}}</strong></div></div><div class="sp-config-form"><label>Intervalo visual da grade (minutos)<input v-model.number="booking.slot_minutes" type="number" min="5" max="240" step="5"/></label><label class="sp-check"><input v-model="booking.allow_any_professional" type="checkbox"/>Permitir “qualquer responsável disponível” quando Profissional estiver visível</label></div></article>
          <article class="sp-config-card wide"><span class="sp-card-kicker">Conteúdo complementar</span><h2>Orientações da página</h2><p>Use esta área apenas para informações adicionais. Código executável e conteúdo inseguro são removidos antes da publicação.</p><textarea v-model="booking.custom_html" class="sp-html-editor" rows="9" placeholder="<section><h2>Antes de agendar</h2><p>Orientações...</p></section>"/></article>
        </div><div class="sp-config-actions"><button class="sp-primary-action" :disabled="saving" @click="saveBooking"><Save :size="17"/>{{saving?'Salvando...':'Salvar página de agendamento'}}</button><button class="sp-secondary-action" @click="openPublic"><ExternalLink :size="17"/>Visualizar página</button></div>
      </template>

      <template v-else-if="active==='messages'">
        <section class="sp-message-guide"><div><Info :size="22"/><div><strong>Como personalizar as mensagens</strong><span>Os nomes técnicos usados internamente pela plataforma não aparecem para você. Trabalhe apenas com o objetivo da mensagem e o texto que o cliente deve receber.</span></div></div><ol><li>Escolha WhatsApp ou E-mail.</li><li>Ative somente as etapas que deseja comunicar.</li><li>Use as variáveis para inserir dados reais automaticamente.</li><li>Salve cada mensagem depois da alteração.</li></ol></section>
        <section class="sp-template-help"><strong>Variáveis disponíveis</strong><code>{{variableHelp}}</code><span>As variáveis entre chaves são substituídas pelos dados do atendimento no momento do envio.</span></section>
        <div class="sp-template-columns">
          <section><header><MessageSquareText :size="20"/><div><span>Canal</span><h2>WhatsApp</h2><small>Mensagens curtas e objetivas funcionam melhor neste canal.</small></div></header><article v-for="item in whatsappTemplates" :key="item.id" class="sp-template-card"><div class="sp-template-card-head"><div><strong>{{friendlyKey(item.key)}}</strong><small>{{templateHelp(item.key)}}</small></div><label><input v-model="item.active" type="checkbox"/>Ativa</label></div><textarea v-model="item.body" rows="6"/><button :disabled="saving" @click="saveTemplate(item)"><Save :size="15"/>Salvar mensagem</button></article><p v-if="!whatsappTemplates.length" class="sp-empty-message">Nenhuma mensagem de WhatsApp disponível.</p></section>
          <section><header><MessageSquareText :size="20"/><div><span>Canal</span><h2>E-mail</h2><small>Use assunto claro e texto com as informações importantes do atendimento.</small></div></header><article v-for="item in emailTemplates" :key="item.id" class="sp-template-card"><div class="sp-template-card-head"><div><strong>{{friendlyKey(item.key)}}</strong><small>{{templateHelp(item.key)}}</small></div><label><input v-model="item.active" type="checkbox"/>Ativa</label></div><input v-if="item.subject!==undefined" v-model="item.subject" class="sp-subject-input" placeholder="Assunto do e-mail"/><textarea v-model="item.body" rows="6"/><button :disabled="saving" @click="saveTemplate(item)"><Save :size="15"/>Salvar e-mail</button></article><p v-if="!emailTemplates.length" class="sp-empty-message">Nenhuma mensagem de e-mail disponível.</p></section>
        </div>
      </template>
    </section>
  </Teleport>
</template>

<style>
body:has(.sp-booking-message-root) .tenant-console .main-content>.view-stack{display:none!important}body:has(.sp-booking-message-root) .tenant-console .page-actions{display:none!important}.sp-booking-message-root{padding:4px 0 28px}.sp-config-loading{min-height:220px;display:flex;align-items:center;justify-content:center;gap:8px;color:#52647c}.sp-booking-config-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sp-config-card{border:1px solid #dfe7f1;border-radius:18px;background:#fff;padding:20px;box-shadow:0 10px 28px rgba(15,23,42,.045)}.sp-config-card.wide{grid-column:1/-1}.sp-config-card>p{color:#52647c;font-size:12px;line-height:1.6}.sp-config-card-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.sp-config-card-head span,.sp-card-kicker,.sp-template-columns header span{font-size:10px;font-weight:900;letter-spacing:.11em;text-transform:uppercase;color:#2563eb}.sp-config-card h2,.sp-template-columns h2{margin:4px 0 8px;color:#10213b}.sp-switch{display:flex;align-items:center;gap:8px;font-size:11px;color:#475569}.sp-switch input{position:absolute;opacity:0}.sp-switch i{width:38px;height:22px;border-radius:999px;background:#cbd5e1;position:relative}.sp-switch i:after{content:"";position:absolute;width:16px;height:16px;border-radius:50%;background:#fff;top:3px;left:3px;transition:.18s}.sp-switch input:checked+i{background:#2563eb}.sp-switch input:checked+i:after{transform:translateX(16px)}.sp-public-url{display:grid;grid-template-columns:1fr auto auto;gap:6px;align-items:center;margin:14px 0;padding:8px;border:1px solid #dbe4ef;border-radius:12px;background:#f8fafc}.sp-public-url code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#334155;font-size:11px}.sp-public-url button{width:34px;height:34px;border:1px solid #dbe4ef;border-radius:9px;background:#fff;color:#2563eb}.sp-config-form{display:grid;gap:11px}.sp-config-form label:not(.sp-check){display:grid;gap:6px;font-size:11px;font-weight:800;color:#334155}.sp-config-form input,.sp-config-form textarea,.sp-html-editor,.sp-template-card textarea,.sp-subject-input{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:11px;background:#fff;color:#0f172a;font:inherit;outline:none}.sp-config-form input,.sp-subject-input{height:44px;padding:0 11px}.sp-config-form textarea,.sp-html-editor,.sp-template-card textarea{padding:11px;resize:vertical;line-height:1.55}.sp-check{display:flex;align-items:center;gap:9px;color:#475569;font-size:12px}.sp-check input{width:17px;height:17px}.sp-html-editor{font-family:"SFMono-Regular",Consolas,monospace;font-size:12px}.sp-config-actions{display:flex;gap:9px;margin-top:14px}.sp-primary-action,.sp-secondary-action,.sp-template-card button{min-height:43px;border-radius:11px;padding:0 14px;display:flex;align-items:center;justify-content:center;gap:7px;font-weight:850}.sp-primary-action,.sp-template-card button{border:0;background:#2563eb;color:#fff}.sp-secondary-action{border:1px solid #dbe4ef;background:#fff;color:#334155}.sp-rule-summary{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:13px 0}.sp-rule-summary>div{display:flex;justify-content:space-between;gap:8px;padding:9px 10px;border-radius:9px;background:#f8fafc;color:#52647c;font-size:10px}.sp-rule-summary strong{color:#183a67}.sp-message-guide{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;margin-bottom:12px;padding:18px;border:1px solid #dbe4ef;border-radius:16px;background:#fff}.sp-message-guide>div{display:flex;align-items:flex-start;gap:10px;color:#2563eb}.sp-message-guide strong,.sp-message-guide span{display:block}.sp-message-guide strong{color:#10213b;font-size:14px}.sp-message-guide span{margin-top:4px;color:#52647c;font-size:11px;line-height:1.5}.sp-message-guide ol{margin:0;padding-left:20px;color:#52647c;font-size:11px;line-height:1.8}.sp-template-help{margin-bottom:14px;padding:14px 16px;border:1px solid #bfdbfe;border-radius:14px;background:#eff6ff;display:grid;gap:5px}.sp-template-help strong{color:#1d4ed8}.sp-template-help code{font-size:11px;color:#334155;overflow-wrap:anywhere}.sp-template-help span{font-size:11px;color:#52647c}.sp-template-columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sp-template-columns>section>header{display:flex;align-items:flex-start;gap:9px;margin-bottom:10px;color:#2563eb}.sp-template-columns header small{display:block;margin-top:3px;color:#64748b;font-size:10px}.sp-template-card{margin-bottom:10px;border:1px solid #e2e8f0;border-radius:15px;background:#fff;padding:15px}.sp-template-card-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:10px}.sp-template-card-head strong,.sp-template-card-head small{display:block}.sp-template-card-head small{max-width:420px;margin-top:4px;color:#64748b;font-size:10px;line-height:1.4;font-weight:500}.sp-template-card-head label{display:flex;gap:5px;align-items:center;color:#64748b;font-size:10px}.sp-template-card textarea{font-family:inherit;font-size:12px}.sp-template-card button{margin-top:8px;min-height:38px;font-size:11px}.sp-subject-input{margin-bottom:8px;font-size:12px}.sp-empty-message{padding:24px;border-radius:14px;background:#f8fafc;color:#64748b;text-align:center}.sp-success{display:flex!important;align-items:center;gap:6px}.spin{animation:sp-bm-spin .8s linear infinite}@keyframes sp-bm-spin{to{transform:rotate(360deg)}}@media(max-width:850px){.sp-booking-config-grid,.sp-template-columns,.sp-message-guide{grid-template-columns:1fr}.sp-config-card.wide{grid-column:auto}.sp-config-actions{display:grid}.sp-config-card{padding:16px}.sp-config-card-head{display:grid}.sp-template-card textarea{min-height:150px}}@media(max-width:520px){.sp-rule-summary{grid-template-columns:1fr}.sp-template-card-head{display:grid}.sp-template-card-head label{min-height:34px}.sp-template-columns>section>header{padding-top:4px}}
</style>
